"""Brahmacharini `results.json` → markdown. Generated, never typed."""

from __future__ import annotations

import json
import sys


def main(path: str) -> int:
    with open(path, encoding="utf-8") as handle:
        r = json.load(handle)
    d = r["dataset"]
    p = d["procedures"]
    out = [
        "<!-- Generated by packages/sati/sati/embed/report.py from the training workflow. Do not edit by hand. -->\n",
        "# Brahmacharini v0 — from observed behaviour to ATT&CK technique\n",
        f"**{d['name']}**: {d['techniques']} techniques; procedures split **by source** — train {p['train']:,}, "
        f"validation {p['validation']:,}, test {p['test']:,}, written about {d['test_sources_unseen']} groups, "
        "malware families, tools and campaigns never seen in training. Each test procedure ranks all techniques.\n",
        "| Retriever | Recall@1 | Recall@5 | Recall@10 | MRR |",
        "|---|---:|---:|---:|---:|",
    ]
    for name, m in r["test"].items():
        label = "**Brahmacharini v0**" if name.startswith("brahmacharini") else name
        out.append(f"| {label} | {m['recall@1']:.3f} | {m['recall@5']:.3f} | {m['recall@10']:.3f} | {m['mrr']:.3f} |")
    out += [
        "",
        f"Epochs chosen on validation sources: {r['best_epoch_by_validation']}.\n",
        "Designed, written and trained by an AI assistant under the owner's direction "
        "([adr/RealDataModels](../../adr/RealDataModels.md)). ATT&CK © MITRE, used under its royalty-free licence.",
    ]
    print("\n".join(out))
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1]))
